const body = $json.body ?? $json;
if (!body || typeof body !== 'object') throw new Error('A JSON request body is required');
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : (r & 3) | 8).toString(16);
});
const allowed = ['ORDER_PLACED','PREPARING','READY_FOR_PICKUP','PARTIALLY_COLLECTED','FULFILLED','CANCELLED'];
if (!allowed.includes(String(body.newStatus))) throw new Error('Unsupported fulfilment status');
if (!/^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(body.orderId ?? ''))) throw new Error('orderId must be a UUID');
const messages = { ORDER_PLACED:'Your shared order was placed.', PREPARING:'Your shared order is being prepared.', READY_FOR_PICKUP:'Your shared order is ready for pickup.', PARTIALLY_COLLECTED:'Part of your shared order was collected.', FULFILLED:'Your shared order was fulfilled.', CANCELLED:'Your shared order was cancelled.' };
return [{ json: { eventId: body.eventId || uuid(), correlationId: body.correlationId || uuid(), orderId: body.orderId, newStatus: body.newStatus, message: messages[body.newStatus], deliveryTargets: ['web_app'], createdAt: new Date().toISOString() } }];
